WITH desired(slug,name,page,description,mechanics) AS (VALUES
('dd-statblock-frey','Frey Divine Stat Block','174-176',
 'Frey is the divine-rank-18 greater Asgardian deity of agriculture, fertility, harvest, sunlight, and elves.',
 '{"deitySlug":"frey","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"greater","divineRank":18,"titles":["God of Sunlight and the Elves"],"symbol":"Ice-blue greatsword","homePlane":"Asgard","alignment":"NG","classes":[{"class":"Ranger","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","sourceSubtype":"Elf","size":"Medium","hitDice":"20d8+200 outsider + 20d10+200 ranger + 20d8+200 cleric","hitPoints":1120,"initiative":"+22, always first","speed":{"land":60},"armorClass":{"total":86,"dexterity":18,"natural":31,"divine":18,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"unarmed":"+76/+71/+66/+61 melee","unarmedDamage":"1d3+8; greater deity maximum 11","spellTouch":{"melee":66,"ranged":76},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":60,"ref":70,"will":59,"greaterDeityAlways20":true},"abilities":{"str":27,"dex":46,"con":30,"int":28,"wis":28,"cha":29},"specialAttacks":{"turnUndeadPerDay":16},"specialQualities":{"printedDamageReduction":"71/+5","printedFireResistance":38,"spellResistance":50,"divineAura":{"radiusMiles":18,"dc":37},"elfTraits":true,"printedFavoredEnemies":{"giants":5,"goblinoids":4,"dragons":3,"aberrations":2,"undead":1},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Automatic Metamagic (quicken cleric spells)","Banestrike (giants)","Command Plants","Control Creatures (elves)","Divine Blessing (Dexterity)","Divine Celerity","Divine Dodge","Divine Radiance","Divine Shield","Extra Domain (Air)","Gift of Life","Increased Damage Reduction","Life and Death","Mass Life and Death","Power of Nature","Shapechange","Speak with Creatures (plants)","Supreme Initiative","True Shapechange","Wound Enemy"],"domainPowers":{"airTurningUsesPerDay":18,"goodSpellsCasterLevelBonus":1,"plantRebukeCommandUsesPerDay":18,"greaterTurningUsesPerDay":18},"spellLikeAbilities":{"casterLevel":28,"goodCasterLevel":29,"saveDc":"37 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/9/8/8/8/8/6/6/6/6","clericBaseDc":"19 + spell level","rangerSpellsPerDay":"6/5/5/5","rangerBaseDc":"19 + spell level"},"possessions":{"skidbladnir":"Dwarf-made vessel that holds all Aesir, travels up to 100 mph across land, sea, or sky, and folds to pocket size.","formerSword":"+5 dancing defending ghost touch keen longsword given to Skirnir in return for arranging Frey''s marriage to Gerd."},"companions":["Blodug-Hofi, legendary horse","Gullin-Bursti, Golden Bristles boar","Skirnir, shield-man and quasi-deity"],"portfolioSense":"Anything affecting plant life and elven welfare, arts, crafts, spellcasting, or warfare; instantaneously and eighteen weeks into past and future.","automaticActions":{"skills":["Craft (metalworking)","Craft (stoneworking)","Knowledge (arcana)","Knowledge (nature)","Knowledge (the planes)","Knowledge (religion)"],"freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any magic item related to command or control of plants.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["good"],"baseDamageReduction":"30/epic","damageReductionWithIncreasedDamageReduction":"35/epic and evil","fireResistance":23,"additionalOutsiderSkillPoints":true,"ranger":{"hitDice":"20d8 instead of 20d10","convertedHitPoints":1080,"additionalSkillPoints":40,"wildEmpathy":true,"favoredEnemyBonusTotal":18,"favoredEnemyDistributionNote":"The official update gives only the total +18 under revised ranger rules; do not invent a replacement per-enemy distribution.","combatStyle":"Recalculate using revised ranger combat-style feats.","bonusAndClassFeatures":["Endurance","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"]},"cleric":"No class-feature change in the official revision.","increasedDamageReduction":"Adds 5 to rank-based DR and an opposed-alignment bypass; neutral-good Frey therefore uses evil as the opposed alignment.","defunctSkills":["Animal Empathy -> wild empathy","Intuit Direction migrated","Scry ranks reassigned","Wilderness Lore -> Survival"]}}'),

('dd-statblock-freya','Freya Divine Stat Block','176-177',
 'Freya is the divine-rank-15 intermediate Asgardian deity of fertility, love, magic, vanity, and battle-dead chosen for Sessrumnir.',
 '{"deitySlug":"freya","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["Goddess of Love and Fertility"],"symbol":"Falcon","homePlane":"Asgard","alignment":"NG","classes":[{"class":"Fighter","level":20},{"class":"Sorcerer","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d10+160 fighter + 20d4+160 sorcerer","hitPoints":920,"initiative":16,"speed":{"land":60,"fly":200,"flyManeuverability":"perfect"},"armorClass":{"total":82,"dexterity":12,"natural":28,"divine":15,"deflection":17},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"longsword":"+69/+64/+59/+54 melee, +5 dancing spell storing longsword","longswordDamage":"1d8+19/17-20","spellTouch":{"melee":63,"ranged":67}},"saves":{"fort":55,"ref":59,"will":55},"abilities":{"str":27,"dex":34,"con":26,"int":27,"wis":27,"cha":44},"specialQualities":{"printedDamageReduction":"50/+4","printedFireResistance":35,"spellResistance":47,"divineAura":{"radiusFeet":1500,"dc":42},"elfTraits":true,"familiar":"cats","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Area Divine Shield","Automatic Metamagic (quicken sorcerer spells)","Control Creatures (any creature that can cast a spell or use a spell-like ability)","Divine Blast","Divine Celerity","Divine Dodge","Divine Inspiration (love and desire)","Divine Shield","Divine Spellcasting","Extra Domain (Charm)","Instant Move","Instant Counterspell","Mass Divine Blast","See Magic","Shapechange"],"domainPowers":{"airTurningUsesPerDay":20,"charmCharismaBoostUsesPerDay":15,"charmCharismaBoost":4,"charmDurationMinutes":1,"goodSpellsCasterLevelBonus":1,"magicDomainUseItemsAsSorcererLevel":20},"spellLikeAbilities":{"casterLevel":25,"goodCasterLevel":26,"saveDc":"42 + spell level"},"spellcasting":{"sorcererSpellsKnownPerDayLevels0To17":"6/11/10/10/10/10/9/9/9/9/3/3/3/3/2/2/2/2","sorcererBaseDc":"29 + spell level"},"possessions":{"cloakOfFeathers":"Allows flight at will with perfect maneuverability and transformation into a falcon using celestial eagle statistics; caster level 20; weight 1 lb.","brisingsNecklace":"Brisingamen, a priceless dwarf-crafted necklace, is named in the narrative but receives no mechanical stat block here."},"portfolioSense":"Romance and romantic passion, plus creation of any object worth more than 10,000 gp; instantaneously and fifteen weeks into the past.","automaticActions":{"skills":["Appraise","Knowledge (arcana)","Spellcraft"],"freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"magic weapons, magic armor, or wondrous items usable by fighters, sorcerers, or wizards","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["good"],"damageReduction":"25/epic","fireResistance":20,"additionalOutsiderSkillPoints":true,"fighter":"No class-feature change in the official revision.","sorcerer":"No class-feature change in the official revision.","divineCelerity":"Uses revised haste.","charmDomain":"Use the revised Charm-domain spell list where applicable.","defunctSkills":["Alchemy -> Craft (alchemy)","Innuendo ranks reassigned","Scry ranks reassigned"]}}'),

('dd-statblock-frigga','Frigga Divine Stat Block','177-179',
 'Frigga is the divine-rank-17 greater Asgardian deity of birth, fertility, love, animals, foresight, and the household.',
 '{"deitySlug":"frigga","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"greater","divineRank":17,"titles":["Goddess of the Atmosphere","Queen of the Gods"],"symbol":"Large cat","homePlane":"Asgard","alignment":"N","classes":[{"class":"Cleric","level":20},{"class":"Wizard","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+160 outsider + 20d8+160 cleric + 20d4+160 wizard","hitPoints":880,"initiative":13,"speed":{"land":60,"fly":200,"flyManeuverability":"perfect"},"armorClass":{"total":75,"dexterity":9,"natural":30,"divine":17,"deflection":9},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"naturalWeapon":"+65/+60/+55/+40 melee, form-dependent natural weapon","naturalWeaponDamage":"form-dependent +8; greater deity maximum damage","spellTouch":{"melee":65,"ranged":66},"greaterDeityAlways20OnAttacks":true,"greaterDeityMaximumDamage":true},"saves":{"fort":57,"ref":58,"will":66,"greaterDeityAlways20":true},"abilities":{"str":27,"dex":28,"con":27,"int":32,"wis":44,"cha":29},"specialAttacks":{"turnUndeadPerDay":16},"specialQualities":{"printedDamageReduction":"52/+4","printedFireResistance":37,"sonicResistance":37,"spellResistance":49,"divineAura":{"radiusMiles":17,"dc":36},"familiar":"cats","teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Reality","Alter Size","Arcane Mastery","Automatic Metamagic (quicken wizard spells)","Call Creatures (animals)","Clearsight","Divine Air Mastery","Extra Domain (Community)","Extra Sense Enhancement (smell)","Gift of Life","Grow Creature (animals)","Increased Energy Resistance (sonic)","Life and Death","Mass Life and Death","Mind of the Beast","Power of Nature","Shapechange","Speak with Creatures (animals)","Spontaneous Wizard Spells","True Shapechange","Wound Enemy"],"domainPowers":{"airTurningUsesPerDay":17,"printedAnimalFriendshipUsesPerDay":17,"communityCalmEmotionsUsesPerDay":17,"divinationSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":27,"divinationCasterLevel":28,"saveDc":"36 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/11/10/10/10/10/8/8/8/8","clericBaseDc":"27 + spell level","wizardSpellsPerDay":"4/7/7/7/6/6/6/6/5/5","wizardBaseDc":"21 + spell level"},"senses":{"normalRangeMiles":17,"smellRangeMiles":34,"remoteSensingCanAnchorToAnimals":true},"portfolioSense":"Anything affecting an animal''s welfare, instantaneously and seventeen weeks into past and future.","automaticActions":{"skills":["Animal Empathy","Handle Animal","Heal","Knowledge (arcana)","Knowledge (religion)","Knowledge (nature)","Scry","Spellcraft","Wilderness Lore"],"freeActionDcMaximum":30,"maximumPerRound":20},"createMagicItems":"Any light or medium armor, simple weapon, bow, or item related to animal care.","avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":[],"damageReduction":"30/epic","fireResistance":22,"additionalOutsiderSkillPoints":true,"cleric":"No class-feature change in the official revision.","wizard":"Apply revised school-specialization rules if relevant.","animalDomain":{"grantedPower":"speak with animals instead of animal friendship","spellListChanges":"Use official revised Animal-domain substitutions."},"communityDomain":"Use official revised Community-domain spell substitutions.","increasedEnergyResistanceSonic":"Existing sonic resistance increases by 10 under the revised ability rather than using the 3.0 20+rank formula.","defunctSkills":["Alchemy -> Craft (alchemy)","Animal Empathy ranks reassigned/wild empathy where applicable","Innuendo ranks reassigned","Scry ranks reassigned","Wilderness Lore -> Survival"]}}'),

('dd-statblock-heimdall','Heimdall Divine Stat Block','179-180',
 'Heimdall is the divine-rank-15 intermediate Asgardian guardian of Bifrost, watchfulness, sight, hearing, and loyalty.',
 '{"deitySlug":"heimdall","pantheon":"asgardian","sourceEdition":"3.0","rankBand":"intermediate","divineRank":15,"titles":["The Bright God","Guardian of Bifrost","Watchman of Asgard","Golden Tooth","The Ram"],"symbol":"Gjallahorn","homePlane":"Asgard","alignment":"LG","classes":[{"class":"Ranger","level":20},{"class":"Cleric","level":20}],"creature":{"type":"Outsider","size":"Medium","hitDice":"20d8+180 outsider + 20d10+180 ranger + 20d8+180 cleric","hitPoints":1060,"initiative":12,"speed":{"land":60},"armorClass":{"total":69,"dexterity":8,"divine":15,"natural":28,"deflection":8},"face":"5 ft. by 5 ft.","reachFeet":5},"attacks":{"longsword":"+76/+71/+66/+61 melee, +5 bane keen lawful longsword","longswordVsEvilOutsider":"+78/+73/+68/+63 melee","longswordDamage":"1d8+36/15-20","longswordDamageVsEvilOutsider":"2d6 plus 1d8+36/15-20","spellTouch":{"melee":66,"ranged":63}},"saves":{"fort":56,"ref":55,"will":64},"abilities":{"str":32,"dex":27,"con":28,"int":27,"wis":44,"cha":27},"specialAttacks":{"turnUndeadPerDay":15},"specialQualities":{"printedDamageReduction":"65/+5","printedFireResistance":35,"spellResistance":67,"divineAura":{"radiusFeet":1500,"dc":33},"printedFavoredEnemies":{"giants":5,"goblinoids":4,"dragons":3,"aberrations":2,"undead":1},"teleportWithoutErrorAtWill":true,"planeShiftAtWill":true},"salientDivineAbilities":["Alter Form","Alter Size","Annihilating Strike","Banestrike (giants)","Battlesense","Clearsight","Divine Inspiration (courage)","Divine Storm","Divine Weapon Focus (longsword)","Divine Weapon Specialization (longsword)","Extra Sense Enhancement (hearing)","Extra Sense Enhancement (sight)","Increased Damage Reduction","Increased Spell Resistance","Irresistible Blows","Shapechange","Sunder and Disjoin","Wound Enemy"],"domainPowers":{"goodSpellsCasterLevelBonus":1,"lawSpellsCasterLevelBonus":1},"spellLikeAbilities":{"casterLevel":25,"goodLawCasterLevel":26,"saveDc":"33 + spell level"},"spellcasting":{"clericSpellsPerDay":"6/11/10/10/10/10/8/8/8/8","clericBaseDc":"27 + spell level","rangerSpellsPerDay":"8/7/7/7","rangerBaseDc":"27 + spell level"},"possessions":{"gjallahorn":"All living creatures may hear it: Listen DC 5 on Asgard, 10 on Midgard, 15 on Niflheim; all Aesir and Vanir hear automatically. A non-Heimdall user needs Perform DC 40 and Use Magic Device DC 40. Mortals within 1 mile save Fort DC 39 or are stunned 1d10 minutes; failure by 5+ also causes permanent deafness. Caster level 25; weight 10 lb."},"senses":{"normalRangeMiles":15,"sightAndHearingRangeMiles":30},"portfolioSense":"All attempts to reach Asgard, instantaneously and fifteen weeks into the past.","automaticActions":{"skills":["Listen","Search","Spot"],"freeActionDcMaximum":25,"maximumPerRound":10},"createMagicItems":{"scope":"magic weapons, armor, and items enhancing Listen, Search, or Spot","maximumMarketPriceGp":200000},"avatarStatus":"No Avatar salient divine ability is present in the printed stat block; no avatar stat block is created.","revision3_5":{"alignmentSubtypes":["good","lawful"],"baseDamageReduction":"25/epic","damageReductionWithIncreasedDamageReduction":"30/epic plus either chaotic or evil bypass requirement, selected for the salient ability","fireResistance":20,"additionalOutsiderSkillPoints":true,"ranger":{"hitDice":"20d8 instead of 20d10","convertedHitPoints":1020,"additionalSkillPoints":40,"wildEmpathy":true,"favoredEnemyBonusTotal":18,"favoredEnemyDistributionNote":"The official update gives only the total +18 under revised ranger rules; do not invent a replacement per-enemy distribution.","combatStyle":"Recalculate using revised ranger combat-style feats.","bonusAndClassFeatures":["Endurance","woodland stride","swift tracker","evasion","camouflage","hide in plain sight"]},"cleric":"No class-feature change in the official revision.","battlesense":"Replaces uncanny dodge and improved uncanny dodge.","increasedDamageReduction":"Adds 5 to rank-based DR and one alignment bypass opposed to lawful-good Heimdall; source revision permits choosing chaotic or evil.","irresistibleBlows":"Chosen-weapon attacks count as adamantine for overcoming DR and hardness.","defunctSkills":["Animal Empathy -> wild empathy","Innuendo ranks reassigned","Intuit Direction migrated","Scry ranks reassigned","Wilderness Lore -> Survival"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT
  'dd-rule-'||d.slug,'dd-3.0',d.page,d.slug,d.name,d.description,
  'Use the structured mechanics payload for the printed Deities and Demigods divine stat block. Printed 3.0 values remain source-of-truth; revision3_5 records official conversion deltas.',
  0,NULL,1,'deity','divine-stat-block',0,1,'dd-asgardian-pantheon',NULL,
  '["deities-and-demigods","asgardian","deity-stat-block","revision-3.5"]',
  d.mechanics
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_rules r WHERE r.source_id='dd-3.0' AND r.slug=d.slug AND r.owner_user_id IS NULL
);